INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷救济济南和莱州饥民", "description": "洪武五年四月己卯，明廷下令救济济南和莱州的饥民。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8d2748ae-8f6b-5639-98eb-e774081de2d7"}, {"title": "明廷开始推行乡饮酒礼", "description": "四月戊戌，明廷开始推行乡饮酒礼。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7617993a-d809-5763-bb98-cfb2fceb2dba"}, {"title": "邓愈进兵散毛各洞", "description": "四月庚子，邓愈率军平定散毛各洞。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "879e7278-97cd-5f91-b282-0e9ff0fcdc60"}, {"title": "徐达在岭北战败", "description": "五月壬子，徐达率军在岭北与元军交战，明军战败。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "30e2782b-1088-5408-9115-617ba1450011"}, {"title": "明廷下诏恢复乱中为奴者的平民身份", "description": "五月，明廷下令让战乱中沦为奴隶的人恢复平民身份，令地方富户借助饥寒者，由官府照料孤寡及残疾者。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e3966179-f7a0-54dd-95e2-676715260e8b"}, {"title": "明廷允许返乡谋生者按劳力耕种", "description": "同月，明廷命恢复生业的流民按家中劳力耕种，不限于过去的田地。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cb014f25-99ce-5077-9e85-c45c50a98923"}, {"title": "明廷规定宦官禁令和宫中女官制度", "description": "六月丙子，明廷规定宦官须遵守的禁令。丁丑，又制定宫中女官的职官制度。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dc0c33d3-7422-57ed-8d4c-21466d7807d1"}, {"title": "冯胜攻克甘肃并击败元军", "description": "六月戊寅，冯胜攻克甘肃，随后在瓜州、沙州追击并大败元军。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8b02d6bd-b34e-52dd-9c6e-acb16e0a0c32"}, {"title": "明廷明确六部职责和年终考核制度", "description": "六月癸巳，明廷明确六部各自职责，并制定年终考核官员政绩的方法。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ec43f0d-f38e-5169-8fb2-ac5323ba8a4d"}, {"title": "李文忠在阿鲁浑河击败元军", "description": "六月甲辰，李文忠在阿鲁浑河击败元军，宣宁侯曹良臣在战事中阵亡。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3d68ef48-9c13-5d84-a208-455ec781fa4e"}, {"title": "明廷制作铁榜告诫功臣", "description": "六月乙巳，明廷制作铁榜，用来告诫开国功臣。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dcd60bd2-c6f1-5a4d-9258-5590afa52068"}, {"title": "明廷赈济山东并免受灾州县田租", "description": "同月，明廷赈济山东饥民，免除受灾州县的田租。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5bce76c3-62c7-504d-b652-dbae3d5e8a80"}, {"title": "汤和在断头山战败", "description": "七月丙辰，汤和率军在断头山与元军交战，明军战败。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b153f686-172a-52f2-b033-94ddb836d36f"}, {"title": "吴良进兵五开、古州", "description": "八月丙申，吴良率军平定五开、古州一带。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "596e46bd-0bdd-5762-a0fb-597475c3407f"}, {"title": "元军进攻云内，同知黄里身亡", "description": "八月甲辰，元军进攻云内，当地同知黄里在这次战事中身亡。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eafd9da8-a8a6-5ab1-bb9b-5d77893ab798"}, {"title": "周德兴进兵婪凤、安田", "description": "九月戊午，周德兴率军平定婪凤、安田一带。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e050453b-0938-53d8-9e20-bb86b176af5a"}, {"title": "冯胜所率军队返回", "description": "十月丁酉，冯胜所率军队返回。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "16ab930a-bde9-5095-8f58-c28ade8ea009"}, {"title": "明廷免除应天等五地田租", "description": "同月，明廷免去应天、太平、镇江、宁国和广德的田租。", "start_year": 1372, "end_year": 1372, "time_original": "洪武五年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b961a191-afb9-5c08-a676-3691d5207001"}, {"title": "纳哈出进攻辽东", "description": "十一月壬申，纳哈出率军进攻辽东。 按原历纪年，事情发生在公元1372至1373年之间。", "start_year": null, "end_year": null, "time_original": "洪武五年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e352c5f6-32b3-5ba3-83f8-98c5ce076233"}, {"title": "明廷召回徐达和李文忠", "description": "十一月，明廷召徐达、李文忠返回。 按原历纪年，事情发生在公元1372至1373年之间。", "start_year": null, "end_year": null, "time_original": "洪武五年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e0381f6d-6a2e-5bd9-bb4a-fb8d9117df9f"}, {"title": "明廷以农桑和学校考核主管官员", "description": "十二月甲戌，明廷下诏，以农耕、蚕桑和办学成绩考核主管官员。", "start_year": 1373, "end_year": 1373, "time_original": "洪武五年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b89338e4-37b3-5ac0-be88-3f3447198682"}, {"title": "邓愈受命征讨吐番", "description": "十二月庚子，邓愈任征西将军，奉命征讨史书所称的吐番。", "start_year": 1373, "end_year": 1373, "time_original": "洪武五年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bda8de0d-f588-56b4-97ff-cc81db16125c"}, {"title": "明廷规定高丽此后三年一贡", "description": "洪武五年，本纪记琐里、占城、高丽、琉球、乌斯藏入贡。高丽使者再来时，明廷告知此后每三年来进贡一次。 按原历纪年，事情发生在公元1372至1373年之间。", "start_year": null, "end_year": null, "time_original": "洪武五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "69dbd99d-1398-503f-99da-c82ae20c4604"}, {"title": "汪广洋被降为广东参政", "description": "洪武6年（1373年）正月，汪广洋被降为广东参政。", "start_year": 1373, "end_year": 1373, "time_original": "洪武6年（1373年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "e31476e6-a411-57e1-8d06-c477ac10130e"}, {"title": "明廷暂时停办科举，改察举人才", "description": "二月乙未，明廷发布命令，暂时停办科举，通过考察和荐举选拔人才。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7afd5c6-e93a-5e1a-ab20-2e1b13c1ed03"}, {"title": "明廷命御史和按察使考察官员", "description": "二月壬寅，明廷命御史、按察使考察地方主管官员。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4e15822e-10f4-513d-b2c0-9a7f4557ef54"}, {"title": "洪武六年三月初一日食", "description": "三月初一，本纪记发生日食。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bd41d43a-8c18-525c-a76d-1048d449d8d3"}, {"title": "明廷向诸王颁布《昭鉴录》", "description": "三月，明廷颁布《昭鉴录》，借此训诫各位藩王。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f564cedc-a938-51a4-bf9a-7435c3a32644"}, {"title": "徐达等奉命加强山西和北平边防", "description": "三月壬子，徐达任征虏大将军，李文忠、冯胜、邓愈、汤和为副将，负责山西、北平的边防。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a17a0cc-237c-5c74-9c94-21787b958a26"}, {"title": "明廷命主管官员上报山川形势图", "description": "四月己丑，明廷命主管官员呈报标出山川险要和平易地形的图。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ab16753-ea09-54b4-a773-e28d20a5f003"}, {"title": "扩廓帖木儿派兵进攻雁门", "description": "六月壬辰，扩廓帖木儿派兵攻打雁门，守方指挥吴均将其击退。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a264531-9ca6-597d-bce3-5e14c0e3bf97"}, {"title": "明廷免除北平等处受灾地区田租", "description": "同月，明廷免去北平、河间、河南、开封、延安、汾州遭灾地区的田租。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ddb8e83d-2b6c-5299-8234-16b025f5e33a"}, {"title": "明廷命户部查灾并抚恤", "description": "七月壬寅，明廷命户部核查渡江以来各省遭受水灾和旱灾的受损情况，从优抚恤灾民。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33662fa0-d7c6-50d4-b851-b97c013111db"}, {"title": "胡惟庸出任右丞相", "description": "洪武6年（1373年）七月，胡惟庸出任右丞相。", "start_year": 1373, "end_year": 1373, "time_original": "洪武6年（1373年）七月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ad9e466b-d2ec-5fb6-b8c8-80a1a54c0eef"}, {"title": "明廷下诏祭祀三皇和历代帝王", "description": "八月乙亥，明廷下诏祭祀三皇和历代帝王。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9070454a-1b15-5aef-a100-960c7a62ce37"}, {"title": "明廷召回徐达和冯胜", "description": "十月辛巳，明廷召徐达、冯胜返回。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8b4fc78c-76f6-5abb-91f7-6385c8b89857"}, {"title": "徐达派将击退进攻大同的元军", "description": "十一月壬子，扩廓帖木儿进攻大同。徐达派部将将其击败，自己继续驻守。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f413efcb-8fae-5bb1-aa89-af91ff335d77"}, {"title": "明廷派刘仁赈济真定", "description": "十一月甲子，明廷派兵部尚书刘仁前去赈济真定饥民。", "start_year": 1373, "end_year": 1373, "time_original": "洪武六年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5cd562e3-908d-5de8-813a-85c2eb27f826"}, {"title": "明廷登记尚未承袭的故功臣子孙", "description": "闰月乙亥，明廷登记尚未承袭封爵的故功臣后代，本纪记二百零九人。 按原历纪年，事情发生在公元1373至1374年之间。", "start_year": null, "end_year": null, "time_original": "洪武六年闰十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ce6d0baf-f6b3-59e9-b925-a904ad619755"}, {"title": "明廷颁定《大明律》", "description": "闰月庚寅，明廷正式颁定《大明律》。 按原历纪年，事情发生在公元1373至1374年之间。", "start_year": null, "end_year": null, "time_original": "洪武六年闰十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "93fa05f0-7625-5e90-8538-71b1e229f448"}, {"title": "明廷命陈叔明暂掌安南国事", "description": "本纪记洪武六年明廷命安南陈叔明暂代掌管国事。 按原历纪年，事情发生在公元1373至1374年之间。", "start_year": null, "end_year": null, "time_original": "洪武六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ced9ca9c-88e1-5616-aa80-9a5631240759"}, {"title": "明廷命王简等在多地屯田", "description": "洪武七年正月甲戌，明廷命都督佥事王简、王诚和平章李伯昇在河南、山东、北平屯田。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf4bb408-9cc3-5c6b-a841-57257f154a58"}, {"title": "吴祯等奉命巡海", "description": "正月，靖海侯吴祯任总兵官，都督於显为副将，巡海缉捕倭寇。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "603cad7c-2b06-5223-ad4c-f178a0bb5a0b"}, {"title": "洪武七年二月初一日食", "description": "二月初一，本纪记发生日食。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f8a0467-bdef-5b2c-a889-cb3f3185a195"}, {"title": "明廷命修曲阜孔庙并设三氏学", "description": "二月戊午，明廷命人修葺曲阜孔子庙，设置孔、颜、孟三氏学。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8715dc9d-0f31-568d-a9ba-ad690a6f2d2c"}, {"title": "明廷因旱蝗免去多地租税", "description": "二月，平阳、太原、汾州、历城、汲县遭遇旱灾和蝗灾，明廷免去这些地方的租税。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "269d80b1-9f68-5802-8caa-342aa956b78c"}, {"title": "蓝玉击败元军后攻克兴和", "description": "四月己亥，都督蓝玉在白酒泉击败元军，随后攻取兴和。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d667a93b-60c1-54ac-9fef-19fded57c3ca"}, {"title": "陆龄奉命进兵永州、道州等地", "description": "四月壬寅，金吾指挥陆龄进兵永州、道州等地，将其平定。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0360be6d-eca9-5099-bc25-06834cf8c16a"}, {"title": "明廷免去真定等受灾府州县田租", "description": "五月丙子，明廷免去真定等四十二个遭灾府、州、县的田租。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7cfc7b27-45d8-50d3-b741-00add6b6cf85"}, {"title": "明廷赈济苏州饥民", "description": "五月辛巳，明廷赈济苏州饥民，本纪记三十万户。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a19008b5-6dc2-5636-8b7b-622576fa9dd4"}, {"title": "明廷减半苏州等地最重田租", "description": "五月癸巳，明廷减去苏州、松江、嘉兴和湖州最重的那部分田租的一半。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d2e7c542-4cd4-5489-a161-5930291b0ddd"}, {"title": "明廷免冰雹和蝗灾地区田租", "description": "六月，陕西的平凉、延安、靖宁、鄜州遭冰雹，山西、山东、北平和河南遭蝗灾。明廷免除受灾地区田租。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "edc20d76-3fde-525d-9446-f184a2f2c40e"}, {"title": "李文忠在大宁和高州击败元军", "description": "七月甲子，李文忠在大宁、高州击败元军。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3712349e-c9a8-5185-b0da-24bf39caa2b7"}, {"title": "登州和莱州遭到沿海侵扰", "description": "七月壬申，登州和莱州遭到史书所称的倭寇侵扰。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2da1636d-502e-5d03-9a1a-ebe9d877415f"}, {"title": "明廷命官府赡养阵亡军士的困难家属", "description": "八月辛丑，明廷下诏，军士战死后，父母、妻子或子女无法自行生活的，由官府供养。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "01131686-3b03-5fb3-9147-7b28c5e22534"}, {"title": "明廷命官府资送战乱离散人员和困难家属", "description": "明廷命官府帮助避兵离散的百姓和客死者的老幼家属返回。官员死在远方任所，妻儿无力返回的，官府提供车船和路费。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2d1ea038-0077-55b6-8531-9dcef6aecad7"}, {"title": "明廷赈济河间等地并减免租税", "description": "八月庚申，明廷赈济河间、广平、顺德、真定饥民，并免除租税。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2b585cb9-f125-5324-8397-4c49b80d3039"}, {"title": "明廷遣买的里八剌归还北方", "description": "九月丁丑，明廷遣崇礼侯买的里八剌返回北方，并写信给继位的元朝君主。", "start_year": 1374, "end_year": 1374, "time_original": "洪武七年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aec09cf1-c509-5ef3-800f-a77c91874671"}, {"title": "纳哈出进攻辽阳，吴寿击退来军", "description": "十一月壬戌，纳哈出进攻辽阳，明朝千户吴寿将来军击退。 按原历纪年，事情发生在公元1374至1375年之间。", "start_year": null, "end_year": null, "time_original": "洪武七年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d21bf604-91e8-56d5-adb8-d72c84abb4ec"}]'::jsonb)
